files.hooks/register.ts:
// canopy — your project's file tree beside the chat, lit by what Claude reads, edits and commits.
// This is the only file that touches the mods API ($). The modules beside it decide what to
// show; this one lists folders, asks git, watches Claude's tool calls, keeps the state the
// pane is drawn from, and draws it.
import { atom, read, update } from 'claude-code'
import { allows, anyHot, heat, litDirs, markAll, settle, unread, type Activity, type MarkKind, type Marks } from './activity.ts'
import { changesTree, isCommit, readPaths, touchesGit } from './bashpaths.ts'
import { badgeFor, COMMIT_STATUS_ARGV, committed, HEAD_ARGV, NO_GIT, parseStatus, STATUS_ARGV, withinPrefix, type GitState } from './git.ts'
import {
  anchorFor, ancestors, flatten, ignoreRules, isHidden, join, own, put, relativeTo, toEntries, type Entry, type Ignore, type Listing,
} from './tree.ts'
import { isPlain, paneLines, printable, rowKey, type Icons, type Line, type PaneStatus, type Seg } from './view.ts'

type Options = { start: 'on' | 'off'; activity: Activity; ignore: string; follow: 'on' | 'off'; icons: Icons }

const PANE = 'canopy'
const DOCK_COLUMNS = 44
const TICK_MS = 250
const GIT_TIMEOUT_MS = 5_000
// Claude's own file tools. Any other tool naming a file by an absolute path counts too: as a
// write when its name says edit or write, else as a read.
const FILE_TOOLS = new Set(['Read', 'Edit', 'Write', 'NotebookEdit'])

// What the pane is drawn from. $.state survives a hot reload; a drawing that reads it redraws
// when it changes.
const marksA = atom({ plugin: 'canopy', key: 'marks' } as const, {} as Marks)
const gitA = atom({ plugin: 'canopy', key: 'git' } as const, NO_GIT)
const expandedA = atom({ plugin: 'canopy', key: 'expanded' } as const, [] as string[])
const collapsedA = atom({ plugin: 'canopy', key: 'collapsed' } as const, [] as string[])

// Module state: rebuilt by scanning, so losing it to a reload costs one rescan.
let settings: Options = { start: 'on', activity: 'all', ignore: '', follow: 'on', icons: 'badges' }
let root: string | null = null
let booted = false // a first scan has finished (until then the pane says it is reading)
let rootName = ''
let gitPrefix = ''
let listing: Listing = {}
let listings = 0 // counts finished listings, so a scan knows which ones came after it began
const listedAt = new Map<string, number>()
const misses = new Map<string, number>() // listings in a row that failed, by folder
let ig: Ignore = ignoreRules('', '')
let gitignore: string | null = null // the .gitignore the rules were read from
let frame = 0
let tick = 0
let ticker: { cancel(): void } | null = null
let busy = false // a tick still running when the next one is due lets it pass
let wasHot = false // one more frame once the last hot mark cools
let wasLit = false // one more redraw once the last mark goes cold
let gitDue = false // a file changed: ask git on the next check
let head: string | null | undefined // the commit HEAD named at the last check: null before the first, undefined not known
let followTo: string | null = null
let toasted = false

export function register(on: any, options: Partial<Options>) {
  settings = { ...settings, ...options }

  on('session.start', async ($: any, e: any, next: any) => {
    await boot($)
    try {
      await $.command.register({ name: 'canopy', description: 'Show or hide the project tree', argumentHint: '[refresh]', immediate: true })
    } catch {}
    if (settings.start === 'on' && !(await openPane($)) && !toasted) {
      toasted = true
      $.ui.toast('canopy: run /canopy to open the tree')
    }
    if (root !== null) ensureTicker($)
    return next(e)
  }).catch(($: any, e: any, next: any) => next(e))

  // /clear, /resume and /branch reset $.state: start from a fresh scan.
  on('classic.SessionStart', { source: ['clear', 'resume', 'fork'] }, async ($: any, e: any, next: any) => {
    await boot($)
    return next(e)
  }).catch(($: any, e: any, next: any) => next(e))

  // Observes every tool call and always returns what the tool gave.
  on('tool.call', async ($: any, e: any, next: any) => {
    if (root === null) return next(e)
    const path = pathOf(e)
    const command = e.tool === 'Bash' && typeof e.command === 'string' ? (e.command as string) : null
    // A Read lights its file while it runs, and while it waits for permission.
    const earlier = e.tool === 'Read' && path ? await read($, marksA) : null
    const reading = earlier ? await touch($, [path!], 'read') : {}
    // A commit is judged against the status just before it (null: git could not say).
    const before = command !== null && isCommit(command) ? await readStatus($, COMMIT_STATUS_ARGV) : undefined
    const r = await next(e)
    try {
      if (!r?.deny && !r?.isError) await afterTool($, e.tool, r.result, path, command, before)
      else if (earlier) await update($, marksA, (marks: Marks) => unread(marks, reading, earlier))
    } catch {}
    return r
  }).catch(($: any, e: any, next: any) => next(e))

  on('command.run', { command: 'canopy' }, async ($: any, e: any) => {
    if ((e.args ?? '').trim() === 'refresh') {
      await boot($)
      return { text: paneStatus() === 'unreadable' ? `canopy: can't read ${root ?? 'the project folder'}` : 'canopy: rescanned' }
    }
    const pane = (await $.ui.panes()).find((p: any) => p.id === PANE)
    if (pane?.isShown) {
      await $.ui.close({ id: PANE })
      return {}
    }
    // Open behind another pane's tab (only one pane shows at a time, docked or inline): an open
    // only retitles it, so close it and open it again to bring it to the front.
    if (pane) await $.ui.close({ id: PANE })
    if (root === null) await boot($)
    else await freshen($)
    await openPane($)
    ensureTicker($)
    return {}
  }).catch(($: any, e: any, next: any) => (next.called ? next(e) : { text: 'canopy could not open: ' + next.error.kind }))

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($: any, e: any) => {
    // Drawn again after the ticker stopped (the pane was hidden): keep up from here.
    ensureTicker($)
    const marks = await read($, marksA)
    const git = await read($, gitA)
    const now = await $.clock.now()
    const open = openSet(marks, await read($, expandedA), await read($, collapsedA), now)
    const rows = flatten(rootName, listing, (rel) => open.has(rel))
    // A dock draws the body flush against its edge: one cell of air on the left.
    const dock = e.props?.placement === 'dock'
    const width = Math.max(0, (e.props?.bodyColumns ?? DOCK_COLUMNS) - (dock ? 1 : 0))
    const lines = paneLines({ rows, marks, git, now, frame, width, activity: settings.activity, icons: settings.icons }, paneStatus(), root ?? 'the project folder')
    const elements = $.ui.resolve(e)
    const toggle = (dir: string) => toggleDir($, dir)
    return elements.Box({ flexDirection: 'column', ...(dock ? { paddingLeft: 1 } : {}), children: lines.map((line) => drawLine(elements, line, toggle)) })
  })
}

// Finds the root, reads its .gitignore, lists the open folders and asks git. Safe to repeat.
async function boot($: any): Promise<void> {
  try {
    root = normalRoot(await $.session.root())
  } catch {
    root = null
  }
  try {
    if (root === null) return
    rootName = root.split('/').filter(Boolean).pop() ?? root
    gitPrefix = await readGitPrefix($)
    // Cached listings are replaced folder by folder, so the pane never blinks empty.
    await freshen($)
  } finally {
    booted = true
    $.ui.invalidate('ui.render')
  }
}

// Catches up with the disk and the repository: the ignore rules, the open folders, git.
async function freshen($: any): Promise<void> {
  await readIgnore($)
  await scanVisible($)
  await refreshGit($)
}

// Reads the root's .gitignore into the rules. A missing file means none; a read that fails
// otherwise keeps the rules already read. The next scan applies a change.
async function readIgnore($: any): Promise<void> {
  let text = ''
  try {
    text = await $.fs.read(absolute('.gitignore'))
  } catch (err) {
    if (gitignore !== null && !/ENOENT|no such file/i.test(String(err))) return
  }
  if (text === gitignore) return
  gitignore = text
  ig = ignoreRules(text, settings.ignore)
}

async function openPane($: any): Promise<boolean> {
  try {
    const opened = await $.ui.open({ id: PANE, title: 'Canopy', columns: DOCK_COLUMNS })
    return opened?.isPlaced === true
  } catch {
    return false
  }
}

// Lists one folder into the cache, redrawing when it changed. One failed listing keeps the
// last (a passing hiccup); a folder that fails twice in a row is forgotten, and so drawn closed.
async function scanDir($: any, rel: string): Promise<void> {
  if (root === null) return
  const was = JSON.stringify(own(listing, rel))
  try {
    put(listing, rel, toEntries(await $.fs.list(absolute(rel)), rel, ig))
    misses.delete(rel)
  } catch {
    const missed = (misses.get(rel) ?? 0) + 1
    misses.set(rel, missed)
    if (missed > 1) delete listing[rel]
  }
  listedAt.set(rel, ++listings)
  if (JSON.stringify(own(listing, rel)) !== was) $.ui.invalidate('ui.render')
}

// Lists every folder the tree shows open, parents first (a folder is listed only while its
// parent shows it), then forgets the listings of folders that closed. Scans overlap (a poll,
// a press, a shell command), so a folder open by the end, or listed by another since this
// one began, is kept.
async function scanVisible($: any): Promise<void> {
  const began = listings
  const open = await openDirs($)
  const listed = new Set<string>()
  for (const dir of [...open].sort((a, b) => depth(a) - depth(b))) {
    if (dir !== '' && !hasEntry(dir, 'dir')) continue
    await scanDir($, dir)
    listed.add(dir)
  }
  const openNow = await openDirs($)
  for (const dir of Object.keys(listing)) {
    if (listed.has(dir) || openNow.has(dir) || (listedAt.get(dir) ?? 0) > began) continue
    delete listing[dir]
    listedAt.delete(dir)
    misses.delete(dir)
  }
}

// The folders drawn open: the root, the ones the person opened and the ones Claude is working
// in, less the ones the person closed.
function openSet(marks: Marks, expanded: string[], collapsed: string[], now: number): Set<string> {
  const open = new Set([...litDirs(marks, now), ...expanded])
  for (const dir of collapsed) open.delete(dir)
  return open.add('')
}

async function openDirs($: any): Promise<Set<string>> {
  return openSet(await read($, marksA), await read($, expandedA), await read($, collapsedA), await $.clock.now())
}

// Asks git for the branch and badges and keeps them. When git can't say (it timed out, failed
// to start or broke), the last answer stands and this returns null.
async function refreshGit($: any): Promise<GitState | null> {
  gitDue = false
  const state = await readStatus($)
  if (state !== null && JSON.stringify(await read($, gitA)) !== JSON.stringify(state)) await update($, gitA, () => state)
  if (state !== null && state.branch !== null) await settleClean($, state)
  return state
}

// Files Claude changed that git now calls clean: committed outside Claude when HEAD moved since
// the last check, else put back. Each check notes HEAD, so the next one can tell.
async function settleClean($: any, git: GitState): Promise<void> {
  const now = await readHead($)
  if (now === undefined) return
  const before = head
  head = now
  if (before === undefined) return
  const marks = await read($, marksA)
  const clean = Object.keys(marks).filter((rel) => own(marks, rel)?.change === 'write' && badgeFor(git.files, rel) === null)
  if (clean.length === 0) return
  await update($, marksA, (marks: Marks) => settle(marks, clean, now !== before ? 'committed' : 'reverted'))
}

// The commit HEAD names: null before the first commit, undefined when git can't say.
async function readHead($: any): Promise<string | null | undefined> {
  try {
    const r = await $.process.run([...HEAD_ARGV], { cwd: root, timeoutMs: GIT_TIMEOUT_MS, env: { GIT_OPTIONAL_LOCKS: '0' } })
    return r.exitCode === 0 ? r.stdout.trim() || null : null
  } catch {
    return undefined
  }
}

// One `git status`: the branch and badges; none outside a repository; null when git can't say.
async function readStatus($: any, argv: readonly string[] = STATUS_ARGV): Promise<GitState | null> {
  if (root === null) return null
  try {
    // GIT_OPTIONAL_LOCKS=0: a status never takes the index lock from Claude's own git commands.
    const r = await $.process.run([...argv], { cwd: root, timeoutMs: GIT_TIMEOUT_MS, env: { GIT_OPTIONAL_LOCKS: '0' } })
    if (r.exitCode === 0) return withinPrefix(parseStatus(r.stdout), gitPrefix)
    return /not a git repository/i.test(r.stderr) ? NO_GIT : null
  } catch {
    return null
  }
}

// Where the root sits inside its repository ('web/'), since git names paths from the top.
async function readGitPrefix($: any): Promise<string> {
  try {
    const r = await $.process.run(['git', 'rev-parse', '--show-prefix'], { cwd: root, timeoutMs: GIT_TIMEOUT_MS })
    return r.exitCode === 0 ? r.stdout.trim() : ''
  } catch {
    return ''
  }
}

// Lights files Claude touched and returns the marks it left, by relative path. Only what the
// tree can show counts: a path outside the root, hidden by the ignore rules, missing or a
// folder is left alone.
async function touch($: any, paths: readonly string[], kind: MarkKind, cwd?: string): Promise<Marks> {
  if (root === null || !allows(settings.activity, kind)) return {}
  const lit: string[] = []
  const listed = new Set<string>()
  for (const path of paths) {
    const rel = relativeTo(root, path, cwd ?? root)
    if (rel && !isHidden(rel, ig) && (await showsFile($, rel, kind !== 'read', listed))) lit.push(rel)
  }
  if (lit.length === 0) return {}
  const now = await $.clock.now()
  const marks = await update($, marksA, (marks: Marks) => markAll(marks, lit, kind, now))
  // The folders above now open; one a scan forgot meanwhile is listed again.
  for (const dir of new Set(lit.flatMap(ancestors))) if (!Object.hasOwn(listing, dir)) await scanDir($, dir)
  if (settings.follow === 'on' && kind !== 'commit') followTo = lit[lit.length - 1]!
  ensureTicker($)
  const left: Marks = {}
  for (const rel of lit) {
    const m = own(marks, rel)
    if (m) put(left, rel, m)
  }
  return left
}

// Whether the tree holds `rel` as a file. Lists the folders above it first, root down (they
// open as it lights). A write may have just made the file and folders above it, so a folder
// whose listing lacks the next step is listed again; `listed` keeps that to once per touch.
async function showsFile($: any, rel: string, mayBeNew: boolean, listed: Set<string>): Promise<boolean> {
  const dirs = ancestors(rel)
  for (let i = 0; i < dirs.length; i++) {
    const dir = dirs[i]!
    const holds = () => (i + 1 < dirs.length ? hasEntry(dirs[i + 1]!, 'dir') : hasEntry(rel, 'file'))
    if (!Object.hasOwn(listing, dir) || (mayBeNew && !listed.has(dir) && !holds())) {
      listed.add(dir)
      await scanDir($, dir)
    }
    if (!holds()) return false
  }
  return true
}

// What a finished tool call changed: the file it wrote or read, or what a shell command did.
async function afterTool($: any, tool: string, result: any, path: string | undefined, command: string | null, before: GitState | null | undefined): Promise<void> {
  if (command !== null) return afterBash($, command, result, before)
  if (!path || tool === 'Read') return
  if (/edit|write/i.test(tool)) {
    await touch($, [path], 'write')
    await rulesChanged($, [path])
    gitDue = true
  } else {
    await touch($, [path], 'read')
  }
}

// `before`: the status just before a `git commit` (null when git couldn't say), undefined for
// any other command.
async function afterBash($: any, command: string, result: any, before: GitState | null | undefined): Promise<void> {
  if (changesTree(command)) await scanVisible($)
  const changed: string[] = result?.bashEditDiff?.changedFiles ?? []
  if (changed.length) {
    await touch($, changed, 'write')
    await rulesChanged($, changed)
    gitDue = true
  }
  if (allows(settings.activity, 'read')) await touch($, readPaths(command), 'read', await cwdOf($))
  if (result?.gitOperation?.commit || before !== undefined) {
    const was = before === undefined ? await read($, gitA) : before
    const now = await refreshGit($)
    // Only two answers git gave can say what a commit took.
    if (was !== null && now !== null) await touch($, committed(was, now), 'commit')
  } else if (touchesGit(command)) {
    await refreshGit($)
  }
}

// A write to the root's .gitignore changes what the tree hides: read it again and rescan.
async function rulesChanged($: any, paths: readonly string[]): Promise<void> {
  if (root === null || !paths.some((path) => relativeTo(root!, path) === '.gitignore')) return
  await readIgnore($)
  await scanVisible($)
}

// Opens or closes a folder the person pressed. Their choice outlasts Claude's activity there.
async function toggleDir($: any, dir: string): Promise<void> {
  const without = (dirs: string[]) => dirs.filter((d) => d !== dir)
  if ((await openDirs($)).has(dir)) {
    await update($, expandedA, without)
    await update($, collapsedA, (dirs: string[]) => [...without(dirs), dir])
  } else {
    await update($, collapsedA, without)
    await update($, expandedA, (dirs: string[]) => [...without(dirs), dir])
    await scanVisible($)
  }
  $.ui.invalidate('ui.render')
}

function ensureTicker($: any): void {
  if (ticker === null) ticker = $.clock.every(TICK_MS, () => onTick($))
}

function stopTicker(): void {
  ticker?.cancel()
  ticker = null
}

// Four frames a second while a mark is hot. Every second: follow up on edits (git), let heat
// fade, and stop once the pane is hidden (heat is worked out again when it is drawn). Every
// five seconds while shown, catch what changed outside Claude (a rescan and a git status).
async function onTick($: any): Promise<void> {
  if (busy) return
  busy = true
  try {
    frame++
    tick++
    const now = await $.clock.now()
    const marks = await read($, marksA)
    const hot = anyHot(marks, now)
    if (hot || wasHot) $.ui.invalidate('ui.render')
    wasHot = hot
    if (followTo !== null) await follow($)
    if (tick % 4 !== 0) return
    if (gitDue) await refreshGit($)
    // A pane that can't be asked about counts as hidden. The next drawing or touch restarts.
    const panes = await $.ui.panes().catch(() => [])
    if (root === null || !panes.some((p: any) => p.id === PANE && p.isShown)) return stopTicker()
    const lit = Object.values(marks).some((m) => heat(m, now) !== 'cold')
    if (lit || wasLit) $.ui.invalidate('ui.render')
    wasLit = lit
    if (tick % 20 === 0) await freshen($)
  } catch {
    stopTicker()
  } finally {
    busy = false
  }
}

// Scrolls the pane to the file Claude touched last, or to the closed folder holding it. It
// runs on the tick after the touch, once the row is drawn; a hidden pane just says no.
async function follow($: any): Promise<void> {
  const rel = followTo!
  followTo = null
  const open = await openDirs($)
  try {
    await $.ui.scroll({ in: PANE, to: { key: rowKey(anchorFor(rel, (dir) => open.has(dir))) }, block: 'nearest' })
  } catch {}
}

// One line as one row Box: the guides, then the left side, in a Button when it opens or closes
// a folder (none when a narrow pane cut it away: an empty Button is refused), then the right.
function drawLine(elements: any, line: Line, toggle: (dir: string) => void): any {
  const { Box, Button } = elements
  const children = (line.lead ?? []).map((seg) => drawSeg(elements, seg))
  const left = line.left.map((seg) => drawSeg(elements, seg))
  const dir = line.toggle
  if (dir !== undefined && left.length > 0) children.push(Button({ key: 'dir:' + printable(dir), plain: true, onPress: () => toggle(dir), children: left }))
  else children.push(...left)
  if (line.right.length) children.push(Box({ flexGrow: 1 }), ...line.right.map((seg) => drawSeg(elements, seg)))
  return Box({ key: line.key, flexDirection: 'row', children })
}

// A plain segment is a bare string (one element fewer); a styled one is a Text with only the
// props it sets.
function drawSeg(elements: any, seg: Seg): any {
  if (isPlain(seg)) return seg.text
  return elements.Text({
    ...(seg.color !== undefined ? { color: seg.color } : {}),
    ...(seg.bg !== undefined ? { backgroundColor: seg.bg } : {}),
    ...(seg.bold ? { bold: true } : {}),
    ...(seg.dim ? { dimColor: true } : {}),
    children: [seg.text],
  })
}

function paneStatus(): PaneStatus {
  if (!booted) return 'loading'
  const top = listing['']
  if (root === null || top === undefined) return 'unreadable'
  return top.length === 0 ? 'empty' : 'ready'
}

// The file a tool names: Read/Edit/Write's file_path, NotebookEdit's notebook_path, or another
// tool's file_path or path when absolute (a remote tool's repository path is not on this disk).
function pathOf(e: any): string | undefined {
  const named = [e.file_path, e.notebook_path, e.path].find((p) => typeof p === 'string') as string | undefined
  if (named === undefined) return undefined
  return FILE_TOOLS.has(e.tool) || named.startsWith('/') ? named : undefined
}

async function cwdOf($: any): Promise<string | undefined> {
  try {
    return await $.session.cwd()
  } catch {
    return undefined
  }
}

// Each listing's names, built on first use: a commit of thousands of files asks once per file.
const indexes = new WeakMap<readonly Entry[], Map<string, Entry['kind']>>()

function hasEntry(rel: string, kind: Entry['kind']): boolean {
  const entries = own(listing, parentOf(rel))
  if (entries === undefined) return false
  let index = indexes.get(entries)
  if (index === undefined) {
    index = new Map(entries.map((entry) => [entry.name, entry.kind]))
    indexes.set(entries, index)
  }
  return index.get(rel.slice(rel.lastIndexOf('/') + 1)) === kind
}

function absolute(rel: string): string {
  if (!rel) return root!
  return root === '/' ? '/' + rel : join(root!, rel)
}

function normalRoot(path: string): string {
  return path.length > 1 ? path.replace(/\/+$/, '') : path
}

function parentOf(rel: string): string {
  const slash = rel.lastIndexOf('/')
  return slash < 0 ? '' : rel.slice(0, slash)
}

function depth(rel: string): number {
  return rel === '' ? 0 : rel.split('/').length
}

files.hooks/activity.ts:
// canopy's activity model: what Claude did to each file and how recently. A mark is hot for
// 8 seconds (it moves on screen) and warm for a minute after (its folders stay open). What a
// file went through stays for the whole session: edited, committed or read (see stateOf).
// Pure, no mods API.
import { ancestors, own, put } from './tree.ts'

export type MarkKind = 'read' | 'write' | 'commit'
/**
 * `kind` and `at`: Claude's latest touch. `change`: its latest write or commit, which a later
 * read leaves in place, so an edited file still reads as edited after Claude looks at it again.
 */
export type Mark = { kind: MarkKind; at: number; reads: number; writes: number; change?: 'write' | 'commit' }
export type Marks = Record<string, Mark>
export type Heat = 'hot' | 'warm' | 'cold'
export type Activity = 'all' | 'writes' | 'none'

/**
 * Where a file stands this session, strongest first: Claude is writing it now, changed it and
 * hasn't committed, committed it, is reading it now, or read it.
 */
export type FileState = 'editing' | 'edited' | 'committed' | 'reading' | 'read'

export const HOT_MS = 8_000
export const WARM_MS = 60_000

/** The most marks kept; past it the oldest are dropped, cold ones first. */
export const MAX_MARKS = 2000

/**
 * Records one touch, returning a new object. A read keeps the counts of earlier touches; a read
 * that lands while a write is still hot leaves the write showing (a write outranks a read).
 */
export function mark(marks: Marks, path: string, kind: MarkKind, now: number): Marks {
  return markAll(marks, [path], kind, now)
}

/** mark() for many paths at once (a commit of thousands of files): one copy, one prune. */
export function markAll(marks: Marks, paths: readonly string[], kind: MarkKind, now: number): Marks {
  const out = { ...marks }
  for (const path of paths) put(out, path, touched(own(out, path), kind, now))
  return prune(out, now)
}

function touched(prev: Mark | undefined, kind: MarkKind, now: number): Mark {
  const reads = (prev?.reads ?? 0) + (kind === 'read' ? 1 : 0)
  const writes = (prev?.writes ?? 0) + (kind === 'write' ? 1 : 0)
  const keepWrite = kind === 'read' && prev?.kind === 'write' && heat(prev, now) === 'hot'
  if (keepWrite) return { ...prev!, reads }
  const change = kind === 'read' ? prev?.change : kind
  return change ? { kind, at: now, reads, writes, change } : { kind, at: now, reads, writes }
}

/**
 * Files Claude changed that git now calls clean. A commit took them (one made outside Claude:
 * in a terminal, an editor), so they read as committed; or they were put back (checkout,
 * restore, stash), so each keeps only what Claude read of it, and goes if nothing.
 */
export function settle(marks: Marks, paths: readonly string[], how: 'committed' | 'reverted'): Marks {
  const out = { ...marks }
  for (const path of paths) {
    const m = own(out, path)
    if (m?.change !== 'write') continue
    if (how === 'committed') put(out, path, { ...m, change: 'commit' })
    else if (m.reads > 0) put(out, path, { kind: m.kind, at: m.at, reads: m.reads, writes: m.writes })
    else delete out[path]
  }
  return out
}

/**
 * Takes back reads that never happened (denied or failed). `left` holds the marks the reads
 * left, `earlier` the marks before them. A mark still as its read left it returns to what
 * `earlier` had, or to nothing; one touched again since keeps that touch and loses only the
 * read's count (and goes when nothing is left of it).
 */
export function unread(marks: Marks, left: Marks, earlier: Marks): Marks {
  const out = { ...marks }
  for (const [path, mine] of Object.entries(left)) {
    const now = own(out, path)
    if (now === undefined) continue
    if (sameMark(now, mine)) {
      const before = own(earlier, path)
      if (before) put(out, path, before)
      else delete out[path]
      continue
    }
    const reads = Math.max(0, now.reads - 1)
    if (now.kind === 'read' && reads === 0 && !now.change) delete out[path]
    else put(out, path, { ...now, reads })
  }
  return out
}

function sameMark(a: Mark, b: Mark): boolean {
  return a.kind === b.kind && a.at === b.at && a.reads === b.reads && a.writes === b.writes && a.change === b.change
}

// Keeps MAX_MARKS: past it the oldest go, cold reads first, then cold changes, then the rest.
function prune(marks: Marks, now: number): Marks {
  const extra = Object.keys(marks).length - MAX_MARKS
  if (extra <= 0) return marks
  const keep = (m: Mark) => (heat(m, now) !== 'cold' ? 2 : m.change ? 1 : 0)
  const oldest = Object.entries(marks)
    .sort((a, b) => keep(a[1]) - keep(b[1]) || a[1].at - b[1].at)
    .slice(0, extra)
  for (const [path] of oldest) delete marks[path]
  return marks
}

export function heat(m: Mark | undefined, now: number): Heat {
  if (!m) return 'cold'
  const age = now - m.at
  if (age < HOT_MS) return 'hot'
  return age < HOT_MS + WARM_MS ? 'warm' : 'cold'
}

/**
 * Where a file stands, as the `activity` option lets it show: 'writes' leaves reads out (a
 * file Claude is reading shows what it changed there, if anything), 'none' shows nothing.
 */
export function stateOf(m: Mark | undefined, now: number, activity: Activity = 'all'): FileState | null {
  if (!m || activity === 'none') return null
  const hot = heat(m, now) === 'hot'
  if (hot && m.kind === 'write') return 'editing'
  if (hot && m.kind === 'read' && activity === 'all') return 'reading'
  if (m.change === 'commit') return 'committed'
  if (m.change === 'write') return 'edited'
  return activity === 'all' && m.reads > 0 ? 'read' : null
}

/** Strongest first: what is happening now, then what waits for a commit, then the rest. */
export const STATE_RANK: Readonly<Record<FileState, number>> = { editing: 5, reading: 4, edited: 3, committed: 2, read: 1 }

/**
 * Files Claude changed and hasn't committed, committed, and only read. A file counts by what it
 * went through, not by what it shows this moment: one Claude reads again after changing it
 * still counts as changed.
 */
export function tally(marks: Marks, now: number, activity: Activity = 'all'): { edited: number; committed: number; read: number } {
  const out = { edited: 0, committed: 0, read: 0 }
  for (const m of Object.values(marks)) {
    const state = stateOf(m, now, activity)
    if (state === null) continue
    if (state === 'editing' || m.change === 'write') out.edited++
    else if (m.change === 'commit') out.committed++
    else out.read++
  }
  return out
}

/**
 * Every folder's strongest state inside it, and how many files inside share it, in one pass
 * ('' is the whole tree). A closed folder shows it, so the work inside stays in sight.
 */
export function rollup(marks: Marks, now: number, activity: Activity = 'all'): Map<string, { state: FileState; count: number }> {
  const out = new Map<string, { state: FileState; count: number }>()
  for (const [path, m] of Object.entries(marks)) {
    const state = stateOf(m, now, activity)
    if (state === null) continue
    for (const dir of ancestors(path)) {
      const was = out.get(dir)
      if (!was || STATE_RANK[state] > STATE_RANK[was.state]) out.set(dir, { state, count: 1 })
      else if (was.state === state) was.count++
    }
  }
  return out
}

export function anyHot(marks: Marks, now: number): boolean {
  return Object.values(marks).some((m) => heat(m, now) === 'hot')
}

/** The most recently touched hot file, or null. */
export function newestHot(marks: Marks, now: number): string | null {
  let best: string | null = null
  let at = -Infinity
  for (const [path, m] of Object.entries(marks)) {
    if (heat(m, now) === 'hot' && m.at > at) {
      best = path
      at = m.at
    }
  }
  return best
}

/** How many hot or warm marks lie strictly inside a folder ('' is the whole tree). */
export function hotUnder(marks: Marks, dirRel: string, now: number): number {
  const prefix = dirRel ? dirRel + '/' : ''
  let n = 0
  for (const [path, m] of Object.entries(marks)) {
    if (path.startsWith(prefix) && heat(m, now) !== 'cold') n++
  }
  return n
}

/** hotUnder for every folder at once, in one pass: folder → hot or warm marks inside it. */
export function hotCounts(marks: Marks, now: number): Map<string, number> {
  const counts = new Map<string, number>()
  for (const [path, m] of Object.entries(marks)) {
    if (heat(m, now) === 'cold') continue
    for (const dir of ancestors(path)) counts.set(dir, (counts.get(dir) ?? 0) + 1)
  }
  return counts
}

/** The folders above every hot or warm mark: the tree opens them so the work shows. */
export function litDirs(marks: Marks, now: number): Set<string> {
  return new Set(hotCounts(marks, now).keys())
}

/** Whether the `activity` option lets a kind of touch light the tree. */
export function allows(activity: Activity, kind: MarkKind): boolean {
  if (activity === 'none') return false
  return activity === 'all' || kind !== 'read'
}

files.hooks/bashpaths.ts:
// canopy reads Claude's shell commands for three things: the files a command reads (so they
// light up), whether it changes the tree (so canopy rescans), and whether it changes git
// (so the badges refresh). A light reading, not a shell: anything it can't be sure of is left
// out. Pure, no mods API.

type Token = { text: string; quoted: boolean }

const READ_VERBS = new Set(['cat', 'head', 'tail', 'less', 'more', 'bat', 'nl', 'wc', 'sed', 'awk', 'grep', 'rg'])

// Flags whose value is the next word, per verb.
const VALUE_FLAGS: Record<string, Set<string>> = {
  head: new Set(['-n', '-c']),
  tail: new Set(['-n', '-c']),
  grep: new Set(['-e', '-f', '-m', '-A', '-B', '-C', '-d', '-D', '--regexp', '--file', '--include', '--exclude', '--exclude-dir']),
  rg: new Set(['-e', '-f', '-m', '-A', '-B', '-C', '-g', '-t', '-T', '-r', '-M', '-j', '--regexp', '--file', '--glob', '--iglob', '--type', '--type-not']),
  sed: new Set(['-e', '-f', '-l', '--expression', '--file']),
  awk: new Set(['-F', '-v', '-f']),
  bat: new Set(['-l', '-r', '-H', '-m', '--language', '--line-range', '--highlight-line', '--map-syntax']),
}

// Verbs whose first argument is a pattern or a script, unless a flag already gave one.
const SCRIPT_FLAGS: Record<string, Set<string>> = {
  grep: new Set(['-e', '-f', '--regexp', '--file']),
  rg: new Set(['-e', '-f', '--regexp', '--file']),
  sed: new Set(['-e', '-f', '--expression', '--file']),
  awk: new Set(['-f']),
}

const TREE_VERBS = new Set(['rm', 'mv', 'cp', 'mkdir', 'rmdir', 'touch', 'ln', 'unzip', 'tar', 'tee', 'rsync'])
const GIT_TREE = new Set(['checkout', 'switch', 'stash', 'merge', 'pull', 'rebase', 'reset', 'restore', 'clean', 'rm', 'mv', 'clone', 'apply', 'cherry-pick', 'revert', 'am'])
const GIT_STATUS = new Set(['commit', 'checkout', 'switch', 'stash', 'merge', 'pull', 'rebase', 'reset', 'restore', 'add', 'rm', 'mv', 'cherry-pick', 'revert', 'am', 'apply', 'clean', 'init', 'branch'])
const GIT_VALUE_OPTIONS = new Set(['-C', '-c', '--git-dir', '--work-tree', '--namespace', '--config-env'])
const PACKAGE_MANAGERS = new Set(['npm', 'pnpm', 'yarn', 'bun'])
const PACKAGE_CHANGES = new Set(['install', 'i', 'add', 'remove', 'rm', 'uninstall', 'un', 'ci'])
const PREFIX_WORDS = new Set(['sudo', 'env', 'time', 'nohup', 'command'])

const MAX_READ_PATHS = 8
// Words a path can't be sure of: globs, expansions, substitutions, redirects.
const UNSURE = /[*$`()<>]/

/** The paths a command reads, as written (relative or absolute), at most 8. */
export function readPaths(command: string): string[] {
  const found = new Set<string>()
  for (const words of commands(command)) {
    const verb = verbOf(words)
    if (!READ_VERBS.has(verb)) continue
    for (const path of argumentsOf(verb, words)) found.add(path)
  }
  return [...found].slice(0, MAX_READ_PATHS)
}

/** Whether a command adds, removes or moves files (a rescan is due). */
export function changesTree(command: string): boolean {
  return segments(command).some((tokens) => {
    if (writesFile(tokens)) return true
    const words = stripPrefix(tokens)
    const verb = verbOf(words)
    if (TREE_VERBS.has(verb)) return true
    if (verb === 'git') return GIT_TREE.has(gitSubcommand(words))
    return PACKAGE_MANAGERS.has(verb) && PACKAGE_CHANGES.has(words[1]?.text ?? '')
  })
}

/** Whether a command changes what `git status` reports (or the branch). */
export function touchesGit(command: string): boolean {
  return commands(command).some((words) => verbOf(words) === 'git' && GIT_STATUS.has(gitSubcommand(words)))
}

/** Whether a command makes a commit. */
export function isCommit(command: string): boolean {
  return commands(command).some((words) => verbOf(words) === 'git' && gitSubcommand(words) === 'commit')
}

function commands(command: string): Token[][] {
  return segments(command).map(stripPrefix).filter((words) => words.length > 0)
}

// Splits on && || ; | & and newlines outside quotes, then into words; quotes are removed and
// a word remembers whether any of it was quoted. A '#' at the start of a word ends the line.
function segments(command: string): Token[][] {
  const out: Token[][] = []
  let tokens: Token[] = []
  let text = ''
  let quoted = false
  let inWord = false
  let quote: string | null = null
  const endWord = () => {
    if (inWord) tokens.push({ text, quoted })
    text = ''
    quoted = false
    inWord = false
  }
  const endSegment = () => {
    endWord()
    if (tokens.length) out.push(tokens)
    tokens = []
  }
  for (let i = 0; i < command.length; i++) {
    const c = command[i]!
    const next = command[i + 1]
    if (quote) {
      if (c === quote) quote = null
      else if (c === '\\' && quote === '"' && next !== undefined) text += command[++i]
      else text += c
      continue
    }
    if (c === '"' || c === "'") {
      quote = c
      quoted = true
      inWord = true
    } else if (c === '\\' && next !== undefined) {
      i++
      if (next !== '\n') {
        text += next
        inWord = true
      }
    } else if (c === '#' && !inWord) {
      while (i + 1 < command.length && command[i + 1] !== '\n') i++
    } else if (c === ' ' || c === '\t') {
      endWord()
    } else if (c === '\n' || c === ';') {
      endSegment()
    } else if (c === '|') {
      endSegment()
      if (next === '|' || next === '&') i++
    } else if (c === '&' && next === '&') {
      endSegment()
      i++
    } else if (c === '&' && !(text.endsWith('>') || text.endsWith('<') || next === '>')) {
      endSegment() // a background job
    } else {
      text += c
      inWord = true
    }
  }
  endSegment()
  return out
}

// Drops `sudo` (and its flags), `env`, `time`, `nohup`, `command` and VAR=value words.
function stripPrefix(tokens: Token[]): Token[] {
  let i = 0
  while (i < tokens.length) {
    const t = tokens[i]!.text
    if (PREFIX_WORDS.has(t) || /^[A-Za-z_][A-Za-z0-9_]*=/.test(t)) i++
    else if (i > 0 && t.startsWith('-')) i += t === '-u' || t === '-g' ? 2 : 1
    else break
  }
  return tokens.slice(i)
}

function verbOf(words: Token[]): string {
  const first = words[0]?.text ?? ''
  return first.slice(first.lastIndexOf('/') + 1)
}

// The arguments of a read verb that name files: flags and their values, the pattern or script,
// redirects and anything unsure are left out.
function argumentsOf(verb: string, words: Token[]): string[] {
  const paths: string[] = []
  let needsScript = verb in SCRIPT_FLAGS
  let flagsOver = false
  for (let i = 1; i < words.length; i++) {
    const { text, quoted } = words[i]!
    const redirect = quoted ? null : redirectOf(text)
    if (redirect) {
      if (redirect.target === '') i++
      continue
    }
    if (!flagsOver && text === '--') {
      flagsOver = true
    } else if (!flagsOver && text.startsWith('-') && text.length > 1) {
      if (SCRIPT_FLAGS[verb]?.has(text)) needsScript = false
      if (VALUE_FLAGS[verb]?.has(text)) i++
    } else if (needsScript) {
      needsScript = false
    } else if (text && text !== '-' && !UNSURE.test(text)) {
      paths.push(text)
    }
  }
  return paths
}

// A redirect word: `>`, `2>>`, `&>`, `<`, `<<` (bare: the target is the next word) or with the
// target attached (`>out.txt`, `2>&1`).
function redirectOf(text: string): { op: string; target: string } | null {
  const m = /^(?:\d+|&)?(>>?|<<?<?)(.*)$/.exec(text)
  return m ? { op: m[1]!, target: m[2]! } : null
}

// Whether a segment sends output to a file (not /dev/null, not another descriptor).
function writesFile(tokens: Token[]): boolean {
  for (let i = 0; i < tokens.length; i++) {
    const redirect = tokens[i]!.quoted ? null : redirectOf(tokens[i]!.text)
    if (!redirect || !redirect.op.startsWith('>')) continue
    const target = redirect.target || tokens[i + 1]?.text || ''
    if (target && target !== '/dev/null' && !target.startsWith('&')) return true
  }
  return false
}

// The git sub-command after global options: `git -C app commit` → 'commit'.
function gitSubcommand(words: Token[]): string {
  for (let i = 1; i < words.length; i++) {
    const text = words[i]!.text
    if (GIT_VALUE_OPTIONS.has(text)) i++
    else if (!text.startsWith('-')) return text
  }
  return ''
}

files.hooks/git.ts:
// canopy's view of git: the branch and a badge per changed path, read from
// `git status --porcelain=v1 -b -z`, and which files a commit took. Pure, no mods API.
import { ancestors, own, put } from './tree.ts'

export type Badge = 'M' | 'A' | 'D' | 'R' | 'U'
export type GitState = { branch: string | null; files: Record<string, Badge> }

/** The one git command canopy runs: machine-readable, with the branch, NUL-separated. */
export const STATUS_ARGV: readonly string[] = ['git', 'status', '--porcelain=v1', '-b', '-z']

/**
 * The same, just before a commit: every untracked file by name rather than its new folder as
 * one entry, so committing a new folder can mark each file it took.
 */
export const COMMIT_STATUS_ARGV: readonly string[] = [...STATUS_ARGV, '--untracked-files=all']

/** Outside a repository (or before the first status): no branch, no badges. */
export const NO_GIT: GitState = { branch: null, files: {} }

/** The commit HEAD names; it fails, printing nothing, before the first commit. */
export const HEAD_ARGV: readonly string[] = ['git', 'rev-parse', '--verify', '-q', 'HEAD']

// Most severe first: a folder shows the worst thing inside it.
const SEVERITY: readonly Badge[] = ['D', 'M', 'A', 'R', 'U']

export function parseStatus(out: string): GitState {
  const fields = out.split('\0')
  const files: Record<string, Badge> = {}
  let branch: string | null = null
  for (let i = 0; i < fields.length; i++) {
    const field = fields[i]!
    if (field.startsWith('## ')) {
      branch = branchOf(field.slice(3))
      continue
    }
    if (field.length < 4) continue
    const x = field[0]!
    const y = field[1]!
    // A rename or copy is followed by the path it came from; that field is not an entry.
    if (x === 'R' || x === 'C') i++
    const badge = badgeOf(x, y)
    if (badge) put(files, field.slice(3).replace(/\/$/, ''), badge)
  }
  return { branch, files }
}

function branchOf(line: string): string {
  const unborn = /^(?:No commits yet on|Initial commit on) (.+)$/.exec(line)
  if (unborn) return unborn[1]!
  return line.split('...')[0]!.split(' ')[0]!
}

function badgeOf(x: string, y: string): Badge | null {
  if (x === '!') return null
  if (x === '?') return 'U'
  if (x === 'D' || y === 'D') return 'D'
  if (x === 'R') return 'R'
  if (x === 'A' || x === 'C') return 'A'
  return x !== ' ' || y !== ' ' ? 'M' : null
}

/**
 * A path's own badge; a file inside an untracked folder is untracked too (git reports only
 * the folder).
 */
export function badgeFor(files: Record<string, Badge>, rel: string): Badge | null {
  const mine = own(files, rel)
  if (mine) return mine
  const parts = rel.split('/')
  for (let i = parts.length - 1; i > 0; i--) {
    if (own(files, parts.slice(0, i).join('/')) === 'U') return 'U'
  }
  return null
}

/** The most severe badge inside a folder ('' is the whole tree), or the folder's own. */
export function rollup(files: Record<string, Badge>, dirRel: string): Badge | null {
  const prefix = dirRel + '/'
  let worst = SEVERITY.length
  for (const [path, badge] of Object.entries(files)) {
    if (dirRel !== '' && path !== dirRel && !path.startsWith(prefix)) continue
    worst = Math.min(worst, SEVERITY.indexOf(badge))
  }
  return SEVERITY[worst] ?? (dirRel ? badgeFor(files, dirRel) : null)
}

/** rollup for every folder at once: a lookup built in one pass over the badges. */
export function rollupAll(files: Record<string, Badge>): (dirRel: string) => Badge | null {
  const worst = new Map<string, number>()
  const note = (dir: string, rank: number) => {
    const known = worst.get(dir)
    if (known === undefined || rank < known) worst.set(dir, rank)
  }
  for (const [path, badge] of Object.entries(files)) {
    const rank = SEVERITY.indexOf(badge)
    note(path, rank)
    for (const dir of ancestors(path)) note(dir, rank)
  }
  return (dirRel) => {
    const rank = worst.get(dirRel)
    if (rank !== undefined) return SEVERITY[rank]!
    return dirRel ? badgeFor(files, dirRel) : null
  }
}

/**
 * Porcelain paths are relative to the repository's root. A session rooted in a subfolder
 * (`git rev-parse --show-prefix` says `web/`) keeps the paths under it, relative to it.
 */
export function withinPrefix(state: GitState, prefix: string): GitState {
  if (!prefix) return state
  const files: Record<string, Badge> = {}
  for (const [path, badge] of Object.entries(state.files)) {
    if (path.startsWith(prefix)) put(files, path.slice(prefix.length), badge)
  }
  return { branch: state.branch, files }
}

/** The paths a commit took: changed before, clean after (not even inside an untracked folder). */
export function committed(before: GitState, after: GitState): string[] {
  return Object.keys(before.files).filter((path) => badgeFor(after.files, path) === null).sort()
}

